    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'financial_periods' AND column_name = 'created_at' AND column_default IS NULL) THEN
      ALTER TABLE public."financial_periods" ALTER COLUMN "created_at" SET DEFAULT now();
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'financial_periods' AND column_name = 'updated_at' AND column_default IS NULL) THEN
      ALTER TABLE public."financial_periods" ALTER COLUMN "updated_at" SET DEFAULT now();
    END IF;
END $$;
